// Generated by crew adapters build. Installs crew in a Claude Code cloud session (claude.ai/code); elsewhere it does nothing.
import { execFileSync } from 'node:child_process';

if (process.env.CLAUDE_CODE_REMOTE !== 'true') process.exit(0);
const run = (cmd, args) => {
  try { return execFileSync(cmd, args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], timeout: 240000 }).trim(); } catch { return null; }
};
const DEFAULT = '@gredescerber/agent-crew';
// the version this repo pins (a repo variable, read over REST); a spec that is not a plain npm one falls back to the latest
let spec = run('gh', ['api', 'repos/{owner}/{repo}/actions/variables/CREW_HARNESS', '--jq', '.value']) || DEFAULT;
if (!/^@?[\w./-]+(@[\w.-]+)?$/.test(spec)) spec = DEFAULT;
if (!run('crew', ['--version'])) run('npm', ['install', '-g', spec]);
const version = run('crew', ['--version']);
console.log(version
  ? `crew ${version} is installed in this cloud session. Work through crew as AGENTS.md says: run crew task next and follow its next_actions (crew claim, crew commit, crew pr open). GitHub GraphQL is blocked here; crew talks REST.`
  : 'crew could not be installed in this cloud session (npm install -g failed). Tell the human; do not work around crew with plain git pushes.');
